pub fn murmur2_32(data: &[u8]) -> u32 {
    let n = data.len();
    let mut h: u32 = 0 ^ (n as u32);
    let m: u32 = 0x5bd1e995;
    let mut i = 0;

    while n - i >= 4 {
        let mut k: u32 = (data[i] as u32)
            | ((data[i + 1] as u32) << 8)
            | ((data[i + 2] as u32) << 16)
            | ((data[i + 3] as u32) << 24);

        k = k.wrapping_mul(m);
        k ^= k >> 24;
        k = k.wrapping_mul(m);

        h = h.wrapping_mul(m);
        h ^= k;
        i += 4;
    }

    let r = n - i;
    if r >= 3 {
        h ^= (data[i + 2] as u32) << 16;
    }
    if r >= 2 {
        h ^= (data[i + 1] as u32) << 8;
    }
    if r >= 1 {
        h ^= data[i] as u32;
        h = h.wrapping_mul(m);
    }

    h ^= h >> 13;
    h = h.wrapping_mul(m);
    h ^= h >> 15;

    h
}
