pub fn mix_fasthash32(h: u32) -> u32 {
    let mut h = h ^ (h >> 23);
    h = (h as u64).wrapping_mul(0x2127599bf4325c37u64) as u32;
    // In C, h >> 47 on a uint32_t is defined as 0 because 47 >= 32.
    // Rust panics on shifts >= bit width in debug mode. 
    // We must implement the logic such that it results in 0 to match C behavior.
    let h_shifted = if 47 >= 32 { 0 } else { h >> 47 };
    h ^ h_shifted
