pub fn sum_proper_divisors(n: u32) -> u32 {
    if n < 2 {
        return 0;
    }
    let mut s: u32 = 1;
    let mut i: u32 = 2;
    while (i as u64).wrapping_mul(i as u64) <= n as u64 {
        if n % i == 0 {
            s = s.wrapping_add(i);
            let other = n / i;
            if i != other {
                s = s.wrapping_add(other);
            }
        }
        i = i.wrapping_add(1);
    }
    s
}
